import { DocCategory, DocItem } from './types';
import docsMetaPayload from './data/docsMeta.json';

/**
 * Client-safe docs registry: navigation metadata only, no document markdown.
 *
 * `registry.ts` imports the full `docsData.json` (every doc's markdown). `DocsView`
 * is a client component, so importing that pulled all 22 documents into the browser
 * bundle on every docs page. The markdown now arrives as a prop for the current doc,
 * and full-text search loads `public/docs-search.json` on demand.
 *
 * Generated by scripts/build-docs-meta.ts.
 */

export const docCategories: DocCategory[] = docsMetaPayload.categories as DocCategory[];

export const allDocs: DocItem[] = docsMetaPayload.allDocs as DocItem[];

export function getDocById(id: string): DocItem | undefined {
  if (!id) return undefined;
  const cleanId = id.toLowerCase().trim();
  return allDocs.find(
    (doc) => doc.id.toLowerCase() === cleanId || doc.slug.toLowerCase() === cleanId
  );
}

export function getAdjacentDocs(currentId: string): { prev?: DocItem; next?: DocItem } {
  const index = allDocs.findIndex((doc) => doc.id === currentId || doc.slug === currentId);
  if (index === -1) return {};
  return {
    prev: index > 0 ? allDocs[index - 1] : undefined,
    next: index < allDocs.length - 1 ? allDocs[index + 1] : undefined,
  };
}

let searchCorpus: Record<string, string> | null = null;
let searchCorpusPromise: Promise<Record<string, string>> | null = null;

/** Lower-cased search text per doc. Fetched on first search so the corpus never
 *  lands in the initial bundle. */
export function loadSearchCorpus(): Promise<Record<string, string>> {
  if (searchCorpus) return Promise.resolve(searchCorpus);
  searchCorpusPromise ??= fetch('/docs-search.json')
    .then((res) => (res.ok ? (res.json() as Promise<Record<string, string>>) : {}))
    .catch(() => ({}))
    .then((data) => {
      searchCorpus = data;
      return data;
    });
  return searchCorpusPromise;
}

export function searchDocs(query: string, corpus: Record<string, string> = {}): DocItem[] {
  const q = query.trim().toLowerCase();
  if (!q) return allDocs;

  return allDocs.filter((doc) => {
    return (
      doc.title.toLowerCase().includes(q) ||
      doc.description.toLowerCase().includes(q) ||
      doc.category.toLowerCase().includes(q) ||
      doc.headings.some((h) => h.title.toLowerCase().includes(q)) ||
      (corpus[doc.id] ?? '').includes(q)
    );
  });
}
